fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to its offset from Sunday (0-based).
    // Sunday is 0, Monday 1, ..., Saturday 6.
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day abbreviation"), // input guaranteed valid, so optional
    };
    // If the day is Sunday, days until next Sunday is 7,
    // otherwise 7 - day_index gives the days until next Sunday.
    if day_index == 0 {
        7
    } else {
        7 - day_index
    }
}